using System.Net;
using System.Text;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>A real loopback HTTP server standing in for the provider; records what it receives.</summary>
internal sealed class FakeProvider : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly Task loop;

    public FakeProvider(int status, string body, string contentType = "application/json")
    {
        var port = GetFreePort();
        BaseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"{BaseAddress}");
        listener.Start();
        loop = Task.Run(async () =>
        {
            try
            {
                while (true)
                {
                    var ctx = await listener.GetContextAsync();
                    using var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8);
                    RequestBody = await reader.ReadToEndAsync();
                    Method = ctx.Request.HttpMethod;
                    Path = ctx.Request.Url!.AbsolutePath;
                    RequestContentType = ctx.Request.ContentType;
                    var bytes = Encoding.UTF8.GetBytes(body);
                    ctx.Response.StatusCode = status;
                    ctx.Response.ContentType = contentType;
                    await ctx.Response.OutputStream.WriteAsync(bytes);
                    ctx.Response.Close();
                }
            }
            catch (Exception e) when (e is HttpListenerException or ObjectDisposedException) { }
        });
    }

    public Uri BaseAddress { get; }
    public string? RequestBody { get; private set; }
    public string? Method { get; private set; }
    public string? Path { get; private set; }
    public string? RequestContentType { get; private set; }

    private static int GetFreePort()
    {
        var l = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        l.Start();
        var port = ((IPEndPoint)l.LocalEndpoint).Port;
        l.Stop();
        return port;
    }

    public void Dispose()
    {
        listener.Close();
        loop.Wait(TimeSpan.FromSeconds(2));
    }
}
