using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<AuthorizationOutcome> Authorize(FakeProvider provider)
    {
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        return await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        using var provider = new FakeProvider(200, """{"status":"approved"}""");

        await Authorize(provider);

        Assert.Equal("POST", provider.Method);
        Assert.Equal("/v1/authorizations", provider.Path);
        Assert.StartsWith("application/json", provider.RequestContentType);
        using var doc = JsonDocument.Parse(provider.RequestBody!);
        var root = doc.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        using var provider = new FakeProvider(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(provider));
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        using var provider = new FakeProvider(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }

    [Fact]
    public async Task Unknown_fields_in_the_answer_are_ignored()
    {
        using var provider = new FakeProvider(200, """{"id":"x1","status":"approved","extra":{"a":1}}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(provider));
    }

    [Fact]
    public async Task The_provider_refusing_the_request_with_402_is_a_decline()
    {
        using var provider = new FakeProvider(402, """{"error":"card_refused"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_surface_as_failures_rather_than_decisions(int status)
    {
        using var provider = new FakeProvider(status, """{"error":"nope"}""");

        var ex = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(provider));
        Assert.Equal((HttpStatusCode)status, ex.StatusCode);
    }

    [Fact]
    public async Task A_malformed_body_is_a_failure_not_an_approval()
    {
        using var provider = new FakeProvider(200, "not json");
        await Assert.ThrowsAsync<JsonException>(() => Authorize(provider));
    }

    [Theory]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_does_not_clearly_say_approved_never_approves(string body)
    {
        using var provider = new FakeProvider(200, body);
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }
}
